import { useEffect, useMemo, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { ArrowDown, ArrowRight, ArrowUpRight, Check, Download, FileText, Map as MapIcon, Network, Search, X } from 'lucide-react';
import { LinkedEvidenceMap, type LinkedMapSelection } from '../components/investigation/LinkedEvidenceMap';
import { AtlasNetwork } from '../components/investigation/AtlasNetwork';
import type { AtlasSelection } from '../data/atlasInvestigation';
import { buildMapEvidenceScene } from '../data/mapEvidence';
import { HYPOTHESIS_BUNDLE, HYPOTHESIS_CASES, HYPOTHESIS_SOURCES, HYPOTHESIS_ENTITIES, HYPOTHESIS_EDGES, HYPOTHESIS_TRACKS, HYPOTHESIS_ASSESSMENTS, HYPOTHESIS_STATUSES, HYPOTHESIS_STREAMS, HYPOTHESIS_REGISTRY, HYPOTHESIS_COUNTS, hypothesisCaseRegistry, exportHypothesisCase, type HypothesisCase } from '../data/hypothesisLab';
import coverageRows from '../../research/hypothesis-lab/coverage.json';
import './hypothesis-lab.css';

const MAP_FILTERS = { geographyMode: 'all' as const };
const repository = 'https://github.com/occult-kranti/india-corporate-intelligence/blob/codex/education-funding-intelligence';
const entityLabel = (id: string) => HYPOTHESIS_ENTITIES.get(id)?.label ?? id;
const words = (value: string) => value.replace(/-/g, ' ');
const resultLabels = { supports: 'Supports this narrow test', narrows: 'Narrows the proposition', contradicts: 'Contradicts the proposition', unresolved: 'Unresolved' };
function readSelection(value: string | null): LinkedMapSelection | null {
  if (!value) return null;
  const index = value.indexOf(':'), kind = value.slice(0, index), id = value.slice(index + 1);
  return ['entity', 'relationship', 'record', 'state', 'site'].includes(kind) && id ? { kind, id } as LinkedMapSelection : null;
}

export default function HypothesisLab() {
  const [params, setParams] = useSearchParams();
  const [exported, setExported] = useState(false);
  const dialogRef = useRef<HTMLDialogElement>(null), sourceOpener = useRef<HTMLElement | null>(null), readingRef = useRef<HTMLElement>(null), mapRef = useRef<HTMLDivElement>(null);
  const query = params.get('hl_q') ?? '', track = params.get('hl_track') ?? '', assessment = params.get('hl_assessment') ?? '';
  const view = params.get('hl_view') === 'network' ? 'network' : 'map';
  const includeProposed = params.get('hl_questions') === '1';
  const filtered = useMemo(() => {
    const terms = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
    return HYPOTHESIS_CASES.filter(item => (!track || item.track === track) && (!assessment || item.hypothesis.assessment === assessment) && terms.every(term => `${item.title} ${item.question} ${item.finding} ${item.sector} ${item.period} ${item.hypothesis.proposition} ${item.entityIds.map(entityLabel).join(' ')}`.toLowerCase().includes(term)));
  }, [query, track, assessment]);
  const requestedCase = params.get('hl_case'), item = filtered.find(row => row.id === requestedCase) ?? filtered[0];
  const selection = readSelection(params.get('hl_inspect'));
  const source = HYPOTHESIS_SOURCES.get(params.get('hl_source') ?? '');
  const graph = useMemo(() => item ? hypothesisCaseRegistry(item, { includeProposed }) : { ...HYPOTHESIS_REGISTRY, entities: [], relationships: [], records: [], sources: [] }, [item, includeProposed]);
  const scene = useMemo(() => buildMapEvidenceScene(graph, MAP_FILTERS), [graph]);
  const coverage = useMemo(() => graph.states.map(state => {
    const hub = scene.stateHubs.find(row => row.stateCode === state.code);
    return { stateCode: state.code, name: state.name, entities: hub?.counts.entities ?? 0, relationships: hub?.counts.relationships ?? 0, records: hub?.counts.records ?? 0, coverageRecords: hub?.coverageRecordIds.length ?? 0, associationRecords: hub?.associationRecordIds.length ?? 0, nationalContextRecords: 0, unknownRecords: 0, domains: [] };
  }), [graph, scene]);
  const patch = (changes: Record<string, string | undefined>, replace = false) => {
    const current = new URL(window.location.hash.slice(1), window.location.origin), next = new URLSearchParams(current.search);
    for (const [key, value] of Object.entries(changes)) value ? next.set(key, value) : next.delete(key);
    setParams(next, { replace });
  };
  const choose = (next: LinkedMapSelection | null) => patch({ hl_inspect: next ? `${next.kind}:${next.id}` : undefined });
  const changeCase = (id: string) => { setExported(false); patch({ hl_case: id, hl_inspect: undefined, hl_source: undefined, hl_questions: undefined }); };
  const resetFilters = () => patch({ hl_q: undefined, hl_track: undefined, hl_assessment: undefined, hl_case: undefined, hl_inspect: undefined, hl_questions: undefined });
  const openSource = (id: string, opener?: HTMLElement) => { sourceOpener.current = opener ?? document.activeElement as HTMLElement; patch({ hl_source: id }); };
  const closeSource = () => patch({ hl_source: undefined }, true);
  useEffect(() => { setExported(false); }, [item?.id]);
  useEffect(() => {
    const dialog = dialogRef.current;
    if (source && !dialog?.open) dialog?.showModal();
    if (!source && dialog?.open) { dialog.close(); if (sourceOpener.current?.isConnected) sourceOpener.current.focus({ preventScroll: true }); else mapRef.current?.focus({ preventScroll: true }); }
  }, [source]);
  const citations = (ids: string[]) => <div className="hl-citations">{[...new Set(ids)].map(id => {
    const row = HYPOTHESIS_SOURCES.get(id);
    return row ? <button type="button" key={id} data-hl-source={id} onClick={event => openSource(id, event.currentTarget)}><FileText size={14} aria-hidden="true" /><span>{row.title}<small>{row.publisher} · {row.publishedAt ?? 'publication date not established'}</small></span><ArrowUpRight size={14} aria-hidden="true" /></button> : <p key={id}>Source unavailable: {id}</p>;
  })}</div>;
  const download = (current: HypothesisCase) => {
    const url = URL.createObjectURL(new Blob([JSON.stringify(exportHypothesisCase(current), null, 2)], { type: 'application/json' }));
    const link = document.createElement('a'); link.href = url; link.download = `${current.id.replace(/:/g, '-')}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); setExported(true);
  };
  const jump = (id?: string) => {
    const node = id ? document.getElementById(id) : readingRef.current;
    node?.scrollIntoView({ block: 'start', behavior: 'instant' }); node?.focus({ preventScroll: true });
  };
  const selectedEntity = selection?.kind === 'entity' ? selection.id : selection?.kind === 'relationship' && !selection.id.startsWith('question:') ? graph.relationships.find(row => row.id === selection.id)?.from : undefined;
  const stream = item ? HYPOTHESIS_STREAMS.find(row => row.track === item.track) : undefined;
  const dateRange = useMemo(() => ({ from: item ? [
    ...item.hypothesis.chronology.map(row => row.date),
    ...item.edgeIds.flatMap(id => { const date = HYPOTHESIS_EDGES.get(id)?.date; return date ? [date] : []; }),
    ...(item.decisionAnalysis?.decisionDate ? [item.decisionAnalysis.decisionDate] : []),
    '2014-05-26',
  ].sort()[0] : '2014-05-26', to: HYPOTHESIS_BUNDLE.reviewDate }), [item]);

  return <div className="hypothesis-desk" data-hypothesis-desk="" data-hl-case={item?.id}>
    <header className="hl-header"><div><p className="hl-dateline">Modi administrations · 2014–2026 · reviewed {HYPOTHESIS_BUNDLE.reviewDate}</p><h1>Coordination hypotheses</h1><p>Follow the record. Challenge the explanation.</p></div><div className="hl-header-aside"><p>Selected institutional questions, tested against public records. Unproved connections remain questions.</p><a href={`${repository}/docs/hypothesis-lab/CONTRACT.md`} target="_blank" rel="noreferrer">How this desk works<ArrowUpRight size={14} aria-hidden="true" /></a></div></header>
    <div className="hl-inventory"><span><strong>{HYPOTHESIS_COUNTS.cases}</strong> hypothesis files</span><span><strong>{HYPOTHESIS_COUNTS.recordedEdges}</strong> source-attributed links</span><span><strong>{HYPOTHESIS_COUNTS.tests}</strong> discriminating tests</span><Link to="/funding-investigations">Open the wider research desk<ArrowUpRight size={13} aria-hidden="true" /></Link></div>
    <div className="hl-filters"><label><span>Research theme</span><select aria-label="Research theme" value={track} onChange={event => patch({ hl_track: event.target.value || undefined, hl_case: undefined, hl_inspect: undefined, hl_questions: undefined })}><option value="">All themes</option>{HYPOTHESIS_STREAMS.map(row => <option key={row.track} value={row.track}>{HYPOTHESIS_TRACKS[row.track] ?? words(row.track)} ({row.cases.length})</option>)}</select></label><label><span>Current assessment</span><select aria-label="Current assessment" value={assessment} onChange={event => patch({ hl_assessment: event.target.value || undefined, hl_case: undefined, hl_inspect: undefined, hl_questions: undefined })}><option value="">All assessments</option>{Object.entries(HYPOTHESIS_ASSESSMENTS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label className="hl-search"><span>Find a file or institution</span><span><Search size={16} aria-hidden="true" /><input type="search" aria-label="Find a hypothesis file" value={query} onChange={event => patch({ hl_q: event.target.value || undefined, hl_case: undefined, hl_inspect: undefined, hl_questions: undefined }, true)} placeholder="Programme, institution, decision…" /></span></label>{(query || track || assessment) && <button type="button" className="hl-clear" onClick={resetFilters}>Clear filters</button>}</div>
    <p className="hl-register-count" role="status">{filtered.length} of {HYPOTHESIS_CASES.length} selected files · scope is not complete national or annual coverage</p>
    {requestedCase && !filtered.some(row => row.id === requestedCase) && <p className="hl-notice">The requested file is outside the current filter or unavailable. {item ? 'The first matching file is shown.' : 'Clear the filters to return to the register.'}</p>}

    {item ? <>
      <label className="hl-mobile-case">Selected hypothesis file<select aria-label="Selected hypothesis file" value={item.id} onChange={event => changeCase(event.target.value)}>{filtered.map(row => <option key={row.id} value={row.id}>{row.title}</option>)}</select></label>
      <section className="hl-workspace" aria-label="Hypothesis map and case register">
        <aside className="hl-register" aria-label="Hypothesis file register"><div className="hl-register-title">The working files<span>{String(filtered.length).padStart(2, '0')}</span></div>{filtered.map((row, index) => <button key={row.id} type="button" data-hl-choice={row.id} aria-pressed={item.id === row.id} onClick={() => changeCase(row.id)}><span className="hl-number">{String(index + 1).padStart(2, '0')}</span><span><small>{HYPOTHESIS_TRACKS[row.track]}</small><strong>{row.title}</strong><span className="hl-assessment" data-assessment={row.hypothesis.assessment}>{HYPOTHESIS_ASSESSMENTS[row.hypothesis.assessment]}</span></span></button>)}</aside>
        <div className="hl-map-column"><header className="hl-map-heading"><div><span>{item.period}</span><h2>{item.title}</h2></div><div className="hl-view-toggle" role="group" aria-label="Hypothesis evidence view"><button type="button" aria-pressed={view === 'map'} onClick={() => patch({ hl_view: undefined, hl_inspect: undefined })}><MapIcon size={16} aria-hidden="true" />Map</button><button type="button" aria-pressed={view === 'network'} onClick={() => patch({ hl_view: 'network', hl_inspect: undefined })}><Network size={16} aria-hidden="true" />Network</button></div></header>
          <div className="hl-question-control"><label><input type="checkbox" data-hl-question-layer="" checked={includeProposed} onChange={event => patch({ hl_questions: event.target.checked ? '1' : undefined, hl_inspect: undefined })} /><span>Show questions to test</span></label><span>{includeProposed ? `${item.hypothesis.proposedLinks.length} unproved questions · dashed · no money inferred` : 'Recorded links only · question layer off'}</span></div>
          <div className="hl-map" ref={mapRef} tabIndex={-1} data-hl-view={view} data-hl-questions-visible={includeProposed}>
            {view === 'map' ? <LinkedEvidenceMap key={item.id} registry={graph} sceneRegistry={graph} filters={MAP_FILTERS} selection={selection} onSelectionChange={choose} depth={2} spatial coverage={coverage} selectedState={selection?.kind === 'state' ? selection.id.replace('state:', '') : null} onStateSelect={code => choose(code ? { kind: 'state', id: `state:${code}` } : null)} geographyMode="all" nationalRecords={scene.populations.national.counts.records} unknownRecords={scene.populations.unplaced.counts.records} internationalRecords={scene.populations.international.counts.records} indexLabel="CASE ASSOCIATIONS · NOT PAYMENT ADDRESSES" /> : <AtlasNetwork key={item.id} dateRange={dateRange} registry={graph} evidenceRegistry={graph} selectedEntityId={selectedEntity ?? null} selectedEvidence={selection && !['state', 'site'].includes(selection.kind) ? selection as AtlasSelection : null} onSelectionChange={choose} onSourceSelect={id => openSource(id)} />}
          </div>
          <footer className="hl-map-footer"><p>{item.edgeIds.length} recorded assertions retain their own stage and response. {includeProposed ? 'Dashed analytic questions cannot bridge a recorded money trail.' : 'Select a state hub or switch to Network to inspect identities and their connections.'} {graph.entities.some(row => !row.resolved) && 'Unresolved identities remain in the written file.'}</p><button type="button" onClick={() => jump()}>Read the investigation<ArrowDown size={15} aria-hidden="true" /></button></footer>
        </div>
      </section>

      <section className="hl-reading" key={item.id} ref={readingRef} tabIndex={-1} aria-label="Selected hypothesis file">
        <header className="hl-reading-head"><div><p className="hl-assessment" data-assessment={item.hypothesis.assessment}>{HYPOTHESIS_ASSESSMENTS[item.hypothesis.assessment]}</p><h2>{item.hypothesis.proposition}</h2><p className="hl-assessment-reason">{item.hypothesis.assessmentReason}</p><p className="hl-reading-scope"><strong>Authority:</strong> {item.hypothesis.jurisdiction}</p></div><button type="button" className="hl-export" data-hl-export="" onClick={() => download(item)}>{exported ? <Check size={16} aria-hidden="true" /> : <Download size={16} aria-hidden="true" />}{exported ? 'Packet exported' : 'Export research packet'}</button></header>
        <nav className="hl-reading-nav" aria-label="In this investigation">{[['hl-explanations', 'Competing explanations'], ['hl-tests', 'Evidence tests'], ['hl-decisions', 'Decision table'], ['hl-rules', 'Rules & timeline'], ['hl-recorded', 'Recorded links'], ['hl-next', 'Missing records']].map(([id, label]) => <button type="button" key={id} onClick={() => jump(id)}>{label}</button>)}</nav>
        <div className="hl-support-grid"><section><h3>What the records establish</h3><ul>{item.whatWeKnow.map((text, index) => <li key={index}>{text}</li>)}</ul></section><section className="hl-boundary"><h3>What remains unestablished</h3><ul>{item.whatWeDoNotKnow.map((text, index) => <li key={index}>{text}</li>)}</ul></section></div>
        <section id="hl-explanations" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">01</span><div><h3>Keep rival explanations alive</h3><p>A suspicious-looking pattern can have more than one cause. The discriminating record matters more than a plausible story.</p></div></header><div className="hl-alternatives">{item.hypothesis.alternatives.map((alternative, index) => <article key={alternative.id} data-hl-alternative={alternative.id}><span className="hl-letter">{String.fromCharCode(65 + index)}</span><h4>{alternative.label}</h4><p>{alternative.explanation}</p><div><strong>Record that separates it</strong><p>{alternative.discriminatingRecord}</p></div></article>)}</div><p className="hl-comparison"><strong>Required comparison:</strong> {item.hypothesis.comparison}</p></section>
        <section id="hl-tests" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">02</span><div><h3>Test the proposition against the record</h3><p>These tests were reconstructed after the outcomes were known. They are not preregistered forecasts.</p></div></header>{item.hypothesis.tests.map((test, index) => <article className="hl-test" key={test.id} data-hl-test={test.id}><div className="hl-test-title"><span>{String(index + 1).padStart(2, '0')}</span><h4>{test.question}</h4><span className="hl-result" data-result={test.result}>{resultLabels[test.result]}</span></div><div className="hl-test-expectations"><div><h5>If the hypothesis holds</h5><p>{test.expectedIfTrue}</p></div><div><h5>If an alternative holds</h5><p>{test.expectedIfAlternative}</p></div></div><div className="hl-test-observation"><h5>What was observed</h5><p>{test.observation}</p>{citations(test.sourceIds)}</div><details><summary>Next discriminating record</summary><p>{test.nextRecord}</p><p><strong>Holder:</strong> {test.holder}</p></details></article>)}</section>
        <section className="hl-section hl-proposed" aria-label="Unestablished connections"><header><Network size={24} aria-hidden="true" /><div><h3>The missing connections</h3><p>Questions for document acquisition. Contextual citations do not establish these links.</p></div></header>{item.hypothesis.proposedLinks.length ? item.hypothesis.proposedLinks.map(link => <article key={link.id} data-hl-proposed={link.id}><div className="hl-proposed-route"><span>{entityLabel(link.from)}</span><span aria-label="unestablished connection">⋯ ? ⋯</span><span>{entityLabel(link.to)}</span></div><h4>{link.question}</h4><p><strong>Missing evidence:</strong> {link.missingEvidence}</p><p><strong>Disconfirming evidence:</strong> {link.disconfirmingEvidence}</p>{citations(link.sourceIds)}</article>) : <p>No additional unestablished link is proposed in this file.</p>}</section>
        {item.decisionAnalysis && <section id="hl-decisions" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">03</span><div><h3>At the decision table</h3><p>Formal powers, constraints and observable choices. Possible incentives are not findings about anyone’s private motives.</p></div></header><p className="hl-mono">Decision date · {item.decisionAnalysis.decisionDate ?? 'not established'}</p><div className="hl-actors">{item.decisionAnalysis.actors.map((actor, index) => <article key={`${actor.entityId}-${index}`}><h4>{entityLabel(actor.entityId)}</h4><p><strong>Authority:</strong> {actor.authority}</p><p><strong>Possible institutional incentive:</strong> {actor.incentive}</p><details><summary>Authority sources</summary>{citations(actor.evidenceSourceIds)}</details></article>)}</div><details className="hl-information"><summary>Information available at the time</summary><ul>{item.decisionAnalysis.informationThen.map((entry, index) => <li key={index}>{typeof entry === 'string' ? entry : <>{entry.text}{citations(entry.sourceIds)}</>}</li>)}</ul></details><div className="hl-options">{item.decisionAnalysis.options.map((option, index) => <article key={index}><span>Choice {index + 1}</span><div><h4>{option.label}</h4><p><strong>Observable implication:</strong> {option.expectedObservableOutcome}</p>{citations(option.sourceIds)}</div></article>)}</div><div className="hl-later"><h4>What the later record shows</h4><p>{item.decisionAnalysis.observedOutcome}</p>{citations(item.decisionAnalysis.sourceIds)}</div><ul className="hl-limits">{item.decisionAnalysis.hindsightLimits.map((text, index) => <li key={index}>{text}</li>)}</ul></section>}
        <section id="hl-rules" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">04</span><div><h3>Rules, powers and chronology</h3><p>Read the rule in force at the decision. Later judgments and disclosures remain later outcomes.</p></div></header><div className="hl-rules">{item.hypothesis.rules.map((rule, index) => <article key={index}><span className="hl-mono">{rule.operativePeriod}</span><h4>{rule.title}</h4><p>{rule.requirement}</p>{citations(rule.sourceIds)}</article>)}</div><ol className="hl-timeline">{[...item.hypothesis.chronology].sort((a, b) => a.date.localeCompare(b.date)).map((event, index) => <li key={`${event.date}-${index}`}><div><time dateTime={event.date}>{event.date}</time><span>{event.knowledge === 'contemporaneous' ? 'Contemporaneous record' : 'Later outcome'}</span></div><div><p>{event.event}</p>{citations(event.sourceIds)}</div></li>)}</ol></section>
        <section id="hl-recorded" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">05</span><div><h3>Follow each recorded step</h3><p>Source-attributed assertions, including allegations and qualifications. Amounts at different financial stages cannot be added into a cash trail.</p></div></header>{item.edgeIds.map(id => {
          const edge = HYPOTHESIS_EDGES.get(id);
          return edge && <article key={id} className="hl-edge" data-hl-edge={id}><div className="hl-edge-route"><span>{entityLabel(edge.from)}</span><ArrowRight size={17} aria-label="to" /><span>{entityLabel(edge.to)}</span></div><div><p className="hl-edge-status">{HYPOTHESIS_STATUSES[edge.status]} · {words(edge.stage)} · {edge.date ?? 'event date not established'}</p><h4>{edge.label}</h4>{edge.amount && <p className="hl-amount">{edge.amount.value.toLocaleString('en-IN', { maximumFractionDigits: 20 })} {edge.amount.currency} {edge.amount.unit}<small>{edge.amount.period} · {edge.amount.basis}{edge.amount.overlapGroup ? ` · overlap group: ${edge.amount.overlapGroup}` : ''}</small></p>}<p><strong>Response / qualification:</strong> {edge.response}</p><details><summary>Limits and sources</summary>{edge.limits.map((text, index) => <p key={index}>{text}</p>)}{citations(edge.sourceIds)}</details></div></article>;
        })}<details className="hl-claim-register"><summary>Claim-level attributions and responses ({item.claims.length})</summary>{item.claims.map(claim => <article key={claim.id} data-hl-claim={claim.id}><p className="hl-edge-status">{HYPOTHESIS_STATUSES[claim.status]}</p><h4>{claim.text}</h4><p><strong>Response:</strong> {claim.response}</p><p><strong>Alternative:</strong> {claim.alternative}</p><p><strong>Falsifier:</strong> {claim.falsifier}</p><ul>{claim.missingRecords.map((text, index) => <li key={index}>{text}</li>)}</ul>{citations(claim.sourceIds)}</article>)}</details></section>
        <section id="hl-next" className="hl-section" tabIndex={-1}><header><span className="hl-section-number">06</span><div><h3>Where the investigation goes next</h3><p>Next review target: {item.hypothesis.nextReview}. A scheduled review is not a prediction that misconduct will be found.</p></div></header><div className="hl-next-records">{item.nextRecords.map((row, index) => <article key={index}><span>{String(index + 1).padStart(2, '0')}</span><div><h4>{row.record}</h4><p><strong>Holder:</strong> {row.holder}</p><p>{row.purpose}</p></div></article>)}</div><div className="hl-inference-limits"><h4>Limits on the inference</h4><ul>{[...item.limits, ...item.hypothesis.inferenceLimits].map((text, index) => <li key={index}>{text}</li>)}</ul></div>{stream && <details className="hl-rejected"><summary>Rejected or unestablished joins in this theme ({stream.rejectedJoins.length})</summary><p>Track-wide questions, not additional findings against this file’s participants.</p>{stream.rejectedJoins.map((row, index) => <article key={index}><h4>{entityLabel(row.from)} → {entityLabel(row.to)}</h4><p>{row.proposed}</p><p><strong>Why it was not admitted:</strong> {row.reason}</p>{citations(row.sourceIds)}</article>)}</details>}<details className="hl-source-register"><summary>Full source register for this file ({graph.sources.length})</summary>{citations(graph.sources.map(row => row.id))}</details></section>
      </section>
    </> : <section className="hl-empty"><h2>No hypothesis file matches these filters</h2><p>This describes the selected research register, not an absence of activity or wrongdoing.</p><button type="button" onClick={resetFilters}>Show all hypothesis files</button></section>}

    <section className="hl-continuation" aria-label="Further sectors and open research"><header><h2>Keep the wider system in view</h2><p>Continue into the existing sector registers. The questions below define further work; they are not new allegations or evidence of connections.</p></header><div>{coverageRows.map(row => <details key={row.sector}><summary><span>{row.sector}</span><small>{row.status}</small></summary><p><strong>Authority to distinguish:</strong> {row.authority}</p><p>{row.question}</p><ul>{row.nextRecords.map((record, index) => <li key={index}>{record}</li>)}</ul><Link to={row.route}>Open existing sector records<ArrowUpRight size={14} aria-hidden="true" /></Link></details>)}</div></section>
    <footer className="hl-footer"><p>Network proximity, simultaneous events and institutional benefit do not establish coordination. Source families can repeat the same underlying record. No guilt score, pooled money total or predictive accuracy is claimed.</p><span>{HYPOTHESIS_COUNTS.sources} source entries · {HYPOTHESIS_COUNTS.proposedLinks} unproved link questions · {HYPOTHESIS_COUNTS.rejectedJoins} rejected or unestablished joins retained</span></footer>

    <dialog className="hl-source-dialog" ref={dialogRef} aria-label="Source reader" aria-labelledby="hl-source-title" onCancel={event => { event.preventDefault(); closeSource(); }} onClick={event => { if (event.target === event.currentTarget) closeSource(); }}><div className="hl-source-sheet"><button className="hl-source-close" type="button" aria-label="Close source reader" onClick={closeSource} autoFocus><X size={20} aria-hidden="true" /></button>{source && <><p className="hl-mono">{source.kind} · {source.inspection}</p><h2 id="hl-source-title">{source.title}</h2><p>{source.publisher} · published {source.publishedAt ?? 'date not established'}</p><a href={source.url} target="_blank" rel="noopener noreferrer">Open original source<ArrowUpRight size={16} aria-hidden="true" /></a><h3>Inspected locator</h3><p>{source.locator}</p><h3>Retained passage or labelled summary</h3><p className="hl-excerpt">{source.excerpt}</p><h3>What this source cannot establish</h3>{source.limitations.map((text, index) => <p key={index}>{text}</p>)}<p><strong>Source family:</strong> {source.sourceFamily}</p><p><strong>Retrieved:</strong> {source.accessedAt}</p>{source.capturePath && <a href={`${repository}/${source.capturePath}`} target="_blank" rel="noreferrer">Inspect retained capture<ArrowUpRight size={14} aria-hidden="true" /></a>}{source.sha256 && <p className="hl-hash">SHA-256: {source.sha256}</p>}<small>The checksum identifies retained bytes. It does not certify the claims.</small></>}</div></dialog>
  </div>;
}
